17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.util.Locale;
23	
24	import org.springframework.samples.petclinic.model.Owner;
25	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
26	
27	/**
28	 * Derives an owner's {@code identityKey}, the single value all duplicate detection is based on:
29	 * the SHA-256 hex of {@code normalizedTelephone + '|' + (email or empty) + '|' + soundex(lastName)}.
30	 * Kept as a small standalone unit so the request advice and the response mapper derive the key
31	 * identically.
32	 */
33	public final class OwnerIdentityKey {
34	
35	    private OwnerIdentityKey() {
36	    }
37	
38	    static String of(OwnerFieldsDto owner) {
39	        return of(owner.getTelephone(), owner.getEmail(), owner.getLastName(), owner.getPostcode());
40	    }
41	
42	    public static String of(Owner owner) {
43	        return of(owner.getTelephone(), owner.getEmail(), owner.getLastName(), owner.getPostcode());
44	    }
45	
46	    static String of(String telephone, String email, String lastName, String postcode) {
47	        return sha256Hex(telephone(telephone) + '|' + email(email) + '|' + OwnerSoundex.soundex(lastName));
48	    }
49	
50	    static String telephone(String telephone) {
51	        return OwnerTelephoneNormalizationAdvice.toE164(telephone);
52	    }
53	
54	    static String email(String email) {
55	        return (email == null || email.isBlank()) ? "" : email.strip().toLowerCase(Locale.ROOT);
56	    }
57	
58	    /**
59	     * Stable household identifier: the first 12 hex characters of SHA-256 over
60	     * {@code normalizedLastName + '|' + postcode}, so owners with the same last name and postcode
61	     * share it automatically.
62	     */
63	    public static String householdId(String lastName, String postcode) {
64	        String normalized = lastName.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT)
65	            + '|' + (postcode == null ? "" : postcode.trim());
66	        return sha256Hex(normalized).substring(0, 12);
67	    }
68	
69	    private static String sha256Hex(String value) {
70	        try {
71	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
72	            StringBuilder sb = new StringBuilder(digest.length * 2);
73	            for (byte b : digest) {
74	                sb.append(String.format("%02x", b));
75	            }
76	            return sb.toString();
77	        }
78	        catch (NoSuchAlgorithmException e) {
79	            throw new IllegalStateException(e);
80	        }
81	    }
82	}
