17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.LocalDate;
23	import java.util.Map;
24	
25	import org.springframework.samples.petclinic.model.Owner;
26	
27	/**
28	 * Derives an owner's unified {@code memberId} '<REGION><FY><HASH8><CHK>': the region code (from the
29	 * postcode band, else "UNKNOWN"), the 2-digit fiscal year of the registration date, the first 8
30	 * upper-hex characters of SHA-256 over (normalizedTelephone + lastName), and a single Luhn check
31	 * digit over the digits of the preceding segments. Kept as a small standalone unit so the assigning
32	 * aspect, the response mapper and the segment rule all derive the same identity.
33	 */
34	public final class OwnerMemberId {
35	
36	    private OwnerMemberId() {
37	    }
38	
39	    /** Postcode band (4-digit / 100) -> region code. */
40	    private static final Map<Integer, String> REGION = Map.of(20, "NSW", 30, "VIC", 40, "QLD");
41	
42	    /** The region code derived from the owner's postcode band, or "UNKNOWN". */
43	    public static String region(Owner owner) {
44	        String pc = owner.getPostcode();
45	        int band = pc != null && pc.matches("[0-9]{4}") ? Integer.parseInt(pc) / 100 : -1;
46	        return REGION.getOrDefault(band, "UNKNOWN");
47	    }
48	
49	    /** The base memberId before any collision suffix, or {@code null} when the date is absent. */
50	    public static String base(Owner owner) {
51	        LocalDate registered = owner.getRegistrationDate();
52	        if (registered == null) {
53	            return null;
54	        }
55	        String body = region(owner) + String.format("%02d", OwnerFiscalYear.yearOf(registered) % 100) + hash8(owner);
56	        return body + OwnerCheckDigit.luhn(body);
57	    }
58	
59	    private static String hash8(Owner owner) {
60	        try {
61	            byte[] d = MessageDigest.getInstance("SHA-256")
62	                .digest((owner.getTelephone() + owner.getLastName()).getBytes(StandardCharsets.UTF_8));
63	            return String.format("%02X%02X%02X%02X", d[0], d[1], d[2], d[3]);
64	        }
65	        catch (NoSuchAlgorithmException e) {
66	            throw new IllegalStateException(e);
67	        }
68	    }
69	}
