18	
19	import java.util.Set;
20	
21	import org.springframework.samples.petclinic.model.Owner;
22	
23	/**
24	 * Derives an owner's {@code ownerSegment} as '<TIER>_<AREA>': TIER is 'PREMIUM' when the
25	 * membershipLevel is 3 or more, otherwise 'STANDARD'; AREA is 'METRO' when the locality is a
26	 * known region (NSW, VIC or QLD), otherwise 'REGIONAL'. Kept as a small standalone unit so the
27	 * response mapper can expose the value without growing.
28	 */
29	public final class OwnerSegment {
30	
31	    private OwnerSegment() {
32	    }
33	
34	    /** Known metro regions. */
35	    private static final Set<String> METRO = Set.of("NSW", "VIC", "QLD");
36	
37	    public static String of(Owner owner) {
38	        String tier = OwnerMembershipLevel.of(owner) >= 3 ? "PREMIUM" : "STANDARD";
39	        String area = METRO.contains(OwnerMemberId.region(owner)) ? "METRO" : "REGIONAL";
40	        return tier + "_" + area;
41	    }
42	}
