18	
19	import java.util.Map;
20	
21	import org.springframework.samples.petclinic.model.Owner;
22	
23	/**
24	 * Derives an owner's {@code timezone} as the IANA name pinned to their locality/region via a fixed
25	 * table (NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane), and null when the
26	 * region is absent from it. Kept as a small standalone unit so the response mapper can expose the
27	 * value without growing.
28	 */
29	public final class OwnerTimezone {
30	
31	    private OwnerTimezone() {
32	    }
33	
34	    /** Region code -> IANA timezone. */
35	    private static final Map<String, String> TIMEZONE =
36	        Map.of("NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
37	
38	    public static String of(Owner owner) {
39	        String code = owner.getCustomerCode();
40	        int dash = code == null ? -1 : code.indexOf('-');
41	        return dash < 0 ? null : TIMEZONE.get(code.substring(0, dash));
42	    }
43	}
