27	/**
28	 * Emits an audit trail entry on the dedicated {@code AUDIT} logger whenever a new owner is
29	 * successfully created, carrying the assigned id, memberId, registrationDate and
30	 * membershipLevel. Kept as
31	 * its own small aspect so this rule stays a self-contained unit rather than growing the
32	 * controller or service.
33	 */
34	@Aspect
35	@Component
36	public class OwnerAuditCreationAdvice {
37	
38	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
39	
40	    @Around("execution(* org.springframework.samples.petclinic.service.ClinicService.saveOwner(..)) && args(owner)")
41	    public Object auditCreation(ProceedingJoinPoint joinPoint, Owner owner) throws Throwable {
42	        boolean created = owner.isNew();
43	        Object result = joinPoint.proceed();
44	        if (created) {
45	            AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
46	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
47	                OwnerMembershipLevel.of(owner));
48	        }
49	        return result;
50	    }
51	}
