17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.util.concurrent.atomic.AtomicLong;
20	
21	import org.aspectj.lang.ProceedingJoinPoint;
22	import org.aspectj.lang.annotation.Around;
23	import org.aspectj.lang.annotation.Aspect;
24	import org.slf4j.Logger;
25	import org.slf4j.LoggerFactory;
26	import org.springframework.samples.petclinic.model.Owner;
27	import org.springframework.stereotype.Component;
28	
29	/**
30	 * Emits an immutable, structured {@code OWNER_CREATED} event on the {@code AUDIT} logger whenever a
31	 * new owner is successfully created, carrying a monotonically increasing {@code seq}, the owner id,
32	 * the owner's current primary identifier and the membershipLevel. The identifier is read straight
33	 * from the owner, so it tracks whatever the primary identifier is: the customerCode today, and the
34	 * memberId once the customerCode is unified into it. Kept as its own small aspect so this rule stays
35	 * a self-contained unit rather than growing the controller, service or the plain audit line.
36	 */
37	@Aspect
38	@Component
39	public class OwnerCreatedEventAdvice {
40	
41	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
42	
43	    private final AtomicLong seq = new AtomicLong();
44	
45	    @Around("execution(* org.springframework.samples.petclinic.service.ClinicService.saveOwner(..)) && args(owner)")
46	    public Object emitCreatedEvent(ProceedingJoinPoint joinPoint, Owner owner) throws Throwable {
47	        boolean created = owner.isNew();
48	        Object result = joinPoint.proceed();
49	        if (created) {
50	            AUDIT.info(new OwnerCreatedEvent(seq.incrementAndGet(), owner.getId(),
51	                owner.getCustomerCode(), OwnerMembershipLevel.of(owner)).toJson());
52	        }
53	        return result;
54	    }
55	}
56	
57	/**
58	 * Immutable structured owner-creation event. {@code identifier} is the owner's current primary
59	 * identifier (the customerCode now, the memberId later); {@link #toJson()} renders it under the
60	 * {@code customerCode} key the audit contract names.
61	 */
62	record OwnerCreatedEvent(long seq, Integer ownerId, String identifier, int membershipLevel) {
63	
64	    String toJson() {
65	        return "{\"seq\":" + seq
66	            + ",\"ownerId\":" + ownerId
67	            + ",\"customerCode\":" + quote(identifier)
68	            + ",\"membershipLevel\":" + membershipLevel
69	            + ",\"event\":\"OWNER_CREATED\"}";
70	    }
71	
72	    private static String quote(String value) {
73	        return value == null ? "null" : "\"" + value + "\"";
74	    }
75	}
