35	    @Mapping(target = "salutation", expression = "java(org.springframework.samples.petclinic.rest.advice.OwnerSalutation.of(owner))")
36	    @Mapping(target = "selfLink", expression = "java(\"/api/owners/\" + owner.getId())")
37	    OwnerDto toOwnerDto(Owner owner);
38	
39	    Owner toOwner(OwnerDto ownerDto);
40	
41	    @Mapping(target = "id", ignore = true)
