24	/**
25	 * Assigns the unified {@code memberId} '<REGION><FY><HASH8><CHK>' to each newly-created owner just
26	 * before it is saved, delegating the derivation to {@link OwnerMemberId} and the collision handling
27	 * to the deduplicator. Kept as its own small aspect so this rule stays a self-contained unit rather
28	 * than growing the controller or service.
29	 */
30	@Aspect
31	@Component
32	public class OwnerCustomerCodeAdvice {
33	
34	    private final OwnerCustomerCodeDeduplicator deduplicator;
35	
36	    public OwnerCustomerCodeAdvice(OwnerCustomerCodeDeduplicator deduplicator) {
37	        this.deduplicator = deduplicator;
38	    }
39	
40	    @Before("execution(* org.springframework.samples.petclinic.service.ClinicService.saveOwner(..)) && args(owner)")
41	    public void assignCustomerCode(Owner owner) {
42	        if (owner.isNew() && owner.getCustomerCode() == null) {
43	            owner.setCustomerCode(deduplicator.unique(OwnerMemberId.base(owner)));
44	        }
45	    }
46	}
