17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.time.LocalDate;
20	import java.time.Month;
21	
22	import org.springframework.samples.petclinic.model.Owner;
23	
24	/**
25	 * Fiscal-year helpers for an owner's business-day-adjusted registration date, where the fiscal
26	 * year starts on 1 July, so a July-to-December date belongs to the next calendar year's fiscal
27	 * year. Kept as one tiny, self-contained unit so the membership number, the exposed fiscalYear
28	 * label and the tenure rule all share the same basis without growing a handler.
29	 */
30	public final class OwnerFiscalYear {
31	
32	    private OwnerFiscalYear() {
33	    }
34	
35	    /** Fiscal year of {@code date}: the calendar year, rolled to the next year from 1 July onward. */
36	    public static int yearOf(LocalDate date) {
37	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
38	    }
39	
40	    /** {@code FY<YY>} for the owner's registration date, or {@code null} when it is absent. */
41	    public static String label(Owner owner) {
42	        LocalDate registered = owner.getRegistrationDate();
43	        return registered == null ? null : String.format("FY%02d", yearOf(registered) % 100);
44	    }
45	
46	    /** Whole fiscal years elapsed between the owner's registration date and today (0 when absent). */
47	    static int elapsed(Owner owner) {
48	        LocalDate registered = owner.getRegistrationDate();
49	        return registered == null ? 0 : yearOf(LocalDate.now()) - yearOf(registered);
50	    }
51	}
