17	package org.springframework.samples.petclinic.rest.advice;
18	
19	/**
20	 * Computes the single Luhn check digit (0-9) over the digits contained in a string. Kept as a small
21	 * standalone unit so the memberId derivation can reuse it without growing.
22	 */
23	public final class OwnerCheckDigit {
24	
25	    private OwnerCheckDigit() {
26	    }
27	
28	    static int luhn(String s) {
29	        int sum = 0;
30	        boolean dbl = true;
31	        for (int i = s.length() - 1; i >= 0; i--) {
32	            char c = s.charAt(i);
33	            if (c < '0' || c > '9') {
34	                continue;
35	            }
36	            int d = c - '0';
37	            if (dbl && (d *= 2) > 9) {
38	                d -= 9;
39	            }
40	            sum += d;
41	            dbl = !dbl;
42	        }
43	        return (10 - (sum % 10)) % 10;
44	    }
45	}
