25	/**
26	 * Records, on each newly-created owner just before it is saved, how many owners will share its
27	 * household once this one is stored — the existing members plus this owner. Household membership is
28	 * the computed {@code householdId} the mapper also uses (normalized lastName + postcode), so a size
29	 * of 3+ is exactly what the mapper turns into the GOLD membership tier. Kept as its own small aspect
30	 * so this rule stays a self-contained unit.
31	 */
32	@Aspect
33	@Component
34	public class OwnerHouseholdSizeAdvice {
35	
36	    private final OwnerRepository ownerRepository;
37	
38	    public OwnerHouseholdSizeAdvice(OwnerRepository ownerRepository) {
39	        this.ownerRepository = ownerRepository;
40	    }
41	
42	    @Before("execution(* org.springframework.samples.petclinic.service.ClinicService.saveOwner(..)) && args(owner)")
43	    public void assignHouseholdSize(Owner owner) {
44	        if (owner.isNew() && owner.getHouseholdSize() == null) {
45	            String household = householdKey(owner);
46	            long existing = ownerRepository.findAll().stream()
47	                .filter(other -> household.equals(householdKey(other)))
48	                .count();
49	            owner.setHouseholdSize((int) (existing + 1));
50	        }
51	    }
52	
53	    private static String householdKey(Owner owner) {
54	        return OwnerIdentityKey.householdId(owner.getLastName(), owner.getPostcode());
55	    }
56	}
