40	    public String unique(String base) {
41	        Set<String> used = new HashSet<>();
42	        for (Owner o : owners.findAll()) {
43	            used.add(o.getCustomerCode());
44	        }
45	        String code = base;
46	        for (int n = 2; used.contains(code); n++) {
47	            code = base + "-" + n;
48	        }
49	        return code;
